#!/usr/bin/env python3
"""What's new in v1.4.3: real in-game screenshots, mGBA 0.10.5 engine, all in the same crowded Ilex Forest with overworld encounters on: the glitched follower
on the v1.4.2 ROM (r10, 7866c59a...) and the fixed followers on the v1.4.3 ROM itself (r11, f3ae7a5c...) -> data/whatsnew-v1.4.3.json + site/assets/game/whatsnew/v1.4.3/.
usage: whatsnew_v143.py --workspace <VSC>"""
import argparse, hashlib, json, shutil
from pathlib import Path
ROOT = Path(__file__).resolve().parent.parent
ap = argparse.ArgumentParser(); ap.add_argument("--workspace", default=str(ROOT.parent)); a = ap.parse_args(); WS = Path(a.workspace)
sha = lambda p: hashlib.sha256(Path(p).read_bytes()).hexdigest()
R11 = "f3ae7a5cd80be4d48e6ca3198a6aa683eb28f59fb9204488d9fdbfa7829dbe67"; R10 = "7866c59a7c101b84eeef03ad1a2ea1b066239e3d9a8a58a5e73a828ea3bc45a5"
assert sha(WS / "output/project-blonde-v1.4.3-20261106/Pokemon - Project Blonde.gba") == R11
E_ = "output/project-blonde-v1.4/r11-follower-fixes/evidence/screens"
SHOTS = [("glitch", f"{E_}/1-v142-hooh-glitch.png", "The glitch, in v1.4.2", "The lead fainted and HO-OH took over as the follower. On a screen with many wild Pokémon it appeared as scattered pieces of other sprites."),
         ("hooh", f"{E_}/2-v143-hooh-follows.png", "HO-OH follows normally", "In v1.4.3 the same situation is fixed: HO-OH comes out of its Poké Ball and follows you, even with wild Pokémon all around."),
         ("lugia", f"{E_}/3-v143-lugia-follows.png", "LUGIA too", "Every follower is fixed, large or small. Here LUGIA takes over after the lead faints in the same forest."),
         ("wild", f"{E_}/4-v143-after-wild-battle.png", "After a battle with a wild Pokémon", "Your follower now takes priority on a crowded screen. A few wild Pokémon may step away to make room; they come back as you move on, and shiny ones are kept.")]
out = ROOT / "site/assets/game/whatsnew/v1.4.3"; out.mkdir(parents=True, exist_ok=True); rows = []
from PIL import Image
for i, f, t, c in SHOTS:
    src = WS / f; dst = out / f"{i}.png"; shutil.copyfile(src, dst); assert Image.open(dst).size == (240, 160)
    rows.append({"id": i, "file": dst.name, "title": t, "caption": c, "source": f, "sha256": sha(dst), "rom": R10 if i == "glitch" else R11})
title = ROOT / "site/assets/game/title/title-v1.4.png"; dst = ROOT / "site/assets/game/title/title-v1.4.3.png"; shutil.copyfile(title, dst)
G = {"_about": "Generated by tools/whatsnew_v143.py - do not edit. Screenshots taken in the mGBA 0.10.5 engine: the glitch on the v1.4.2 ROM (r10), the rest on the v1.4.3 ROM itself (r11). The title screen of v1.4.3 still shows v1.4 by owner decision, so the v1.4 title picture is correct.",
     "kind": "story", "before": {"public": "v1.4.2", "build": "r10", "sha256": R10}, "after": {"public": "v1.4.3", "build": "r11", "sha256": R11}, "screenshots_from": {"build": "r11", "sha256": R11, "glitch_from": "r10"},
     "heading": "Followers no longer glitch after your lead faints", "lead": "v1.4.3 is a small bug-fix update. When a large Pokémon such as HO-OH or LUGIA takes over as your follower, it now appears and follows you normally.",
     "link": ["/features/overworld-encounters/", "How overworld encounters work"], "desc": "large followers such as HO-OH and LUGIA no longer glitch after your lead faints",
     "title": {"file": dst.name, "source": "site/assets/game/title/title-v1.4.png", "sha256": sha(dst)}, "shots": rows}
(ROOT / "data/whatsnew-v1.4.3.json").write_text(json.dumps(G, indent=1, ensure_ascii=False) + "\n"); print(len(rows), "shots")
